package com.ruoyi.metal.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import com.ruoyi.common.core.domain.model.LoginUser;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.metal.security.FactoryScope;import com.alibaba.fastjson2.JSON;
class WarehouseWorkOrderContextTest {
 final JdbcTemplate jdbc=mock(JdbcTemplate.class);final FactoryScope scope=mock(FactoryScope.class);final WarehouseService service=new WarehouseService(jdbc,scope);
 void login(String permission){var user=new LoginUser();user.setPermissions(Set.of(permission));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user,null,List.of()));}
 void data(String status){when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String sql=a.getArgument(0);if(sql.contains("FROM metal_work_order WHERE"))return List.of(Map.of("customer","甲方","status",status));if(sql.contains("FROM metal_work_order_item WHERE"))return List.of(Map.of("item_id",12L,"product_id",9007199254740993L,"product_snapshot","{\"code\":\"OLD-CODE\",\"name\":\"历史产品名\",\"specification\":\"历史规格\",\"secret\":\"not returned\"}"));return List.of(Map.of("item_id",12L,"process_id",31L,"process_name","快照工序","sequence_no",1));});}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void warehouseAddReturnsOnlyEntrySnapshot(){login("metal:warehouse-order:add");data("IN_PROGRESS");var result=service.workOrderContext(3L,4L);assertEquals("4",result.workOrderId());assertEquals("3",result.factoryId());assertEquals("甲方",result.customer());assertEquals("9007199254740993",result.items().get(0).productId());assertEquals("历史产品名",result.items().get(0).snapshot().name());assertEquals("31",result.items().get(0).plans().get(0).processId());var json=JSON.parseObject(JSON.toJSONString(result));assertEquals(Set.of("workOrderId","factoryId","customer","items"),json.keySet());assertEquals(Set.of("code","name","specification"),json.getJSONArray("items").getJSONObject(0).getJSONObject("snapshot").keySet());assertFalse(JSON.toJSONString(result).contains("not returned"));verify(scope).check(3L);verify(jdbc,times(3)).queryForList(anyString(),any(Object[].class));}
 @Test void warehouseImportAlsoAllowed(){login("metal:warehouse-order:import");data("WAITING_MATERIAL");assertDoesNotThrow(()->service.workOrderContext(3L,4L));}
 @Test void unrelatedPermissionsNeverQuery(){for(String permission:List.of("metal:warehouse-order:list","metal:warehouse-order:query","metal:warehouse:add","metal:warehouse:list","metal:inventory:add","metal:process-batch:add","metal:work-order:query")){login(permission);assertEquals(403,assertThrows(ServiceException.class,()->service.workOrderContext(3L,4L)).getCode());}verifyNoInteractions(jdbc);}
 @Test void factoryScopeCheckedBeforeReading(){login("metal:warehouse-order:add");doThrow(new ServiceException("跨厂",403)).when(scope).check(9L);assertThrows(ServiceException.class,()->service.workOrderContext(9L,4L));verifyNoInteractions(jdbc);}
 @Test void missingOrWrongFactoryOrderDoesNotReadChildren(){login("metal:warehouse-order:add");assertThrows(ServiceException.class,()->service.workOrderContext(3L,4L));verify(jdbc).queryForList(contains("factory_id=? AND del_flag='0'"),eq(4L),eq(3L));verify(jdbc,times(1)).queryForList(anyString(),any(Object[].class));}
 @Test void completedLegacyAndVoidStatesRejected(){login("metal:warehouse-order:add");for(String status:List.of("COMPLETED","PENDING","APPROVED","REJECTED","VOID")){data(status);assertThrows(ServiceException.class,()->service.workOrderContext(3L,4L));}}
 @Test void invalidIdentifiersRejectedBeforeQuery(){login("metal:warehouse-order:add");assertThrows(ServiceException.class,()->service.workOrderContext(null,4L));assertThrows(ServiceException.class,()->service.workOrderContext(3L,0L));verifyNoInteractions(jdbc);}
 @Test void adminWorksWithoutRoleGrants(){when(scope.isAdmin()).thenReturn(true);data("IN_PROGRESS");assertDoesNotThrow(()->service.workOrderContext(3L,4L));}
}
